var reduce=!!(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var news=[
 {h:'Nvidia lifts Q3 outlook on data-centre demand',s:'NVDA',d:'+3.24%',i:'HIGH'},
 {h:'Waller signals patience on the rate path',s:'DXY',d:'-0.41%',i:'MED'},
 {h:'Brent slips as OPEC+ weighs November hike',s:'BZ',d:'-1.82%',i:'HIGH'},
 {h:'Boeing books 40-jet order from Emirates',s:'BA',d:'+1.12%',i:'MED'},
 {h:'Pfizer late-stage trial meets endpoint',s:'PFE',d:'+4.60%',i:'LOW'},
 {h:'Ten-year yield tops 4.30% after weak auction',s:'US10Y',d:'+6bp',i:'HIGH'},
 {h:'Costco August comps edge past consensus',s:'COST',d:'+0.87%',i:'LOW'}
];
var i=0,mins=9*60+34,paused=false,timer=null;
function two(n){return (n<10?'0':'')+n;}
function clk(m){return two(Math.floor(m/60)%24)+':'+two(m%60);}
function make(d,time,cls){
 var li=document.createElement('li');
 li.className='t29-newswire-impact-item'+(cls?' '+cls:'');
 var up=d.d.charAt(0)==='+';
 li.innerHTML='<span class="t29-newswire-impact-meta">'+
  '<span class="t29-newswire-impact-time">'+time+'</span>'+
  '<span class="t29-newswire-impact-tag t29-newswire-impact-'+d.i.toLowerCase()+'">'+d.i+'</span>'+
