  '</span><span class="t29-newswire-impact-h">'+d.h+'</span>';
 return li;
}
function push(seed){
 var d=news[i%news.length];i++;mins+=1+(i%3);
 feed.insertBefore(make(d,clk(mins),reduce?'':(seed?'t29-newswire-impact-seed':'t29-newswire-impact-enter')),feed.firstChild);
 var live=feed.querySelectorAll('.t29-newswire-impact-item:not(.t29-newswire-impact-out)');
 if(live.length>3){
  var last=live[live.length-1];
  if(reduce){if(last.parentNode)last.parentNode.removeChild(last);}
  else{last.className+=' t29-newswire-impact-out';window.setTimeout(function(){if(last.parentNode)last.parentNode.removeChild(last);},300);}
 }
}
push(true);push(true);push(true);
if(reduce){btn.textContent='NEXT';btn.removeAttribute('aria-pressed');btn.addEventListener('click',function(){push(false);});}
else{
 timer=window.setInterval(function(){
  if(!root.isConnected){window.clearInterval(timer);return;}
  if(!paused)push(false);
 },3200);
 btn.addEventListener('click',function(){
  paused=!paused;btn.textContent=paused?'RESUME':'PAUSE';
  btn.setAttribute('aria-pressed',paused?'true':'false');
  if(paused){root.className+=' t29-newswire-impact-paused';}
  else{root.className=root.className.replace(/\s*t29-newswire-impact-paused/,'');}
 });
}

