.t29-edgar-ping-btn:focus-visible{outline:2px solid #4ea3ff;outline-offset:2px}
@keyframes t29-edgar-ping-draw{to{stroke-dashoffset:0}}
@keyframes t29-edgar-ping-fade{to{opacity:1}}
@keyframes t29-edgar-ping-pulse{0%{box-shadow:0 0 0 0 rgba(125,184,255,.6)}70%{box-shadow:0 0 0 6px rgba(125,184,255,0)}100%{box-shadow:0 0 0 0 rgba(125,184,255,0)}}
@keyframes t29-edgar-ping-scan{0%{transform:translateY(0);opacity:0}12%{opacity:.9}88%{opacity:.9}100%{transform:translateY(32px);opacity:0}}
@media (prefers-reduced-motion:reduce){.t29-edgar-ping-page,.t29-edgar-ping-fold,.t29-edgar-ping-l1,.t29-edgar-ping-l2,.t29-edgar-ping-l3{animation:none;stroke-dashoffset:0}.t29-edgar-ping-scan{animation:none;opacity:0}.t29-edgar-ping-new{animation:none}.t29-edgar-ping-ch{animation:none;opacity:1}}

js:
var reduce=!!(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var head=root.querySelector('.t29-edgar-ping-headline');
var ago=root.querySelector('.t29-edgar-ping-ago');
var btn=root.querySelector('.t29-edgar-ping-btn');
var text='Director R. Kaplan reports open-market purchase in HAL';
if(reduce){head.textContent=text;}
else{
 var frag=document.createDocumentFragment();
 for(var i=0;i<text.length;i++){
  var s=document.createElement('span');
  s.className='t29-edgar-ping-ch';
  s.textContent=text.charAt(i);
  s.style.animationDelay=(600+i*16)+'ms';
  frag.appendChild(s);
 }
 head.appendChild(frag);
}
var mins=2,timer=window.setInterval(function(){
 if(!root.isConnected){window.clearInterval(timer);return;}
 mins++;ago.textContent=mins+'m ago';
},60000);
btn.addEventListener('click',function(){
 if(root.className.indexOf('t29-edgar-ping-read')>-1)return;
 root.className+=' t29-edgar-ping-read';
 root.querySelector('.t29-edgar-ping-new').textContent='READ';
 btn.textContent='ARCHIVED';
});
